{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/menu-row.json
    One dish on a menu board: name, optional badge, a dotted leader to the price, then the summary and the portion/weight. Used by MenuBoard; Codex kind `dish`.
    Props (p): dish, prices. *}
{var $v_dish = ($p['dish'] ?? null)}
{var $v_prices = ($p['prices'] ?? 'show')}
{capture $c_6}
  {capture $c_4}
    {capture $c_1}
      {=og_text(og_get($v_dish, ['name']))}
    {/capture}
    {=og_include('compose/Inline.latte', ['class' => 'font-semibold', 'children' => (string) $c_1])|noescape}
    {if og_t(og_get($v_dish, ['badge']))}
      {capture $c_2}
        {=og_text(og_get($v_dish, ['badge']))}
      {/capture}
      {=og_include('compose/Badge.latte', ['variant' => 'outline', 'size' => 'sm', 'children' => (string) $c_2])|noescape}
    {/if}
    {if og_t(og_eq($v_prices, 'show'))}
      {=og_include('compose/Inline.latte', ['class' => 'flex-1 border-b border-dotted border-border', 'attrs' => og_attrs(['aria-hidden', 'true'])])|noescape}
      {capture $c_3}
        {=og_text(og_money(og_get($v_dish, ['price']), og_get($v_dish, ['currency'])))}
      {/capture}
      {=og_include('compose/Inline.latte', ['class' => 'font-semibold', 'attrs' => og_attrs(['data-testid', 'price']), 'children' => (string) $c_3])|noescape}
    {/if}
  {/capture}
  {=og_include('compose/Box.latte', ['class' => 'flex items-baseline gap-2', 'children' => (string) $c_4])|noescape}
  {capture $c_5}
    {=og_text(og_tpl('{0} · {1}', [og_get($v_dish, ['summary']), og_get($v_dish, ['weight'])]))}
  {/capture}
  {=og_include('compose/Inline.latte', ['class' => 'text-sm text-muted-foreground', 'children' => (string) $c_5])|noescape}
{/capture}
{=og_include('compose/ListItem.latte', ['class' => 'flex flex-col gap-0 border-b border-border py-2', 'attrs' => og_attrs(['data-testid', 'item']), 'children' => (string) $c_6])|noescape}
